// TestMediaE2E_ItemMediaServing is the media-preview QA depth (box 4.1, probe
// 0023777e45c1b1b9 re-run at itest depth): a HERMETIC black-box proof that the
// real built server serves real media bytes over GET /api/v1/items/{id}/media.
// Two REAL fixture libraries are scanned through the real subprocess pipeline —
// an IMAGE library (stdlib-encoded JPEG; the photo-original channel via
// parsed.absolute_path) and a TV library (ffmpeg-generated Matroska; the tv
// chain has no frame-grabber, so it is also the deterministic
// thumb-without-the-fact leg) — and the media endpoint is then exercised end to
// end: no-token 401, authenticated 200 with EXACT fixture bytes (bytes.Equal
// against the files on disk), Content-Type/ETag/Cache-Control headers,
// If-None-Match revalidation to 304, 404 for an unknown id, 404 for the thumb
// variant without the frame-grabber fact, and 400 for an unknown variant. No
// in-process fakes; the shared harness (buildBinary/startServer/scanLibrary/
// listItems/…) is reused as-is.
package itest

import (
	"io"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// mediaDo performs one raw HTTP exchange and returns the status, the response
// headers, and the FULL body bytes. Unlike doRequest it never JSON-decodes —
// media responses are file bytes, and the bearer-token header logic must still
// apply. A nil token sends no Authorization header (the bearer-gate leg).
func mediaDo(t *testing.T, c *http.Client, method, url, token string) (int, http.Header, []byte) {
	t.Helper()
	req, err := http.NewRequest(method, url, nil)
	if err != nil {
		t.Fatalf("new request %s %s: %v", method, url, err)
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	resp, err := c.Do(req)
	if err != nil {
		t.Fatalf("do %s %s: %v", method, url, err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		t.Fatalf("read %s %s body: %v", method, url, err)
	}
	return resp.StatusCode, resp.Header, body
}

// TestMediaE2E_ItemMediaServing drives the media endpoint against the real
// server + real scanned fixture libraries (see the file header for the
// contract legs).
func TestMediaE2E_ItemMediaServing(t *testing.T) {
	if testing.Short() {
		t.Skip("media integration test: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — the fixture libraries cannot be scanned (INV4: optional binary)")
	}
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH — cannot generate the real media fixture the bytes legs require")
	}

	tmp := t.TempDir()
	serverBin := buildBinary(t, tmp, "media-server", "./cmd/mellifera")
	scannerBin := buildBinary(t, tmp, "media-base-scanner", "./plugins/base-scanner")
	tvParserBin := buildBinary(t, tmp, "media-tv-parser", "./plugins/tv-parser")
	imageEnricherBin := buildBinary(t, tmp, "media-image-enricher", "./plugins/image-enricher")

	// Real files on disk: one stdlib JPEG (the photo-original fixture) and one
	// ffmpeg Matroska (the video fixture). The server never learns of them
	// except through a real scan.
	photoRoot := t.TempDir()
	photoRel := "vacation.jpg"
	photoPath := filepath.Join(photoRoot, photoRel)
	imgEncode(t, photoPath, 48, 32, "jpeg")

	tvRoot := t.TempDir()
	tvRel := "Golden Valley S01E01.mkv"
	tvPath := filepath.Join(tvRoot, tvRel)
	makeMedia(t, tvPath)

	token := "media-admin-token"
	baseURL := startServer(t, serverBin, scannerBin, tvParserBin, imageEnricherBin, tmp, token)
	client := &http.Client{Timeout: httpTimeout}

	// --- scan both fixture libraries through the real pipeline ---
	photoLib := mediaCreateLibrary(t, client, baseURL, token, photoRoot, "image", "Media Photo Lib")
	if res := scanLibrary(t, client, baseURL, token, photoLib); res.Discovered != 1 || res.Persisted != 1 {
		t.Fatalf("photo scan discovered=%d persisted=%d, want 1/1; warnings=%v", res.Discovered, res.Persisted, res.Warnings)
	}
	tvLib := mediaCreateLibrary(t, client, baseURL, token, tvRoot, "tv", "Media TV Lib")
	if res := scanLibrary(t, client, baseURL, token, tvLib); res.Discovered != 1 || res.Persisted != 1 {
		t.Fatalf("tv scan discovered=%d persisted=%d, want 1/1; warnings=%v", res.Discovered, res.Persisted, res.Warnings)
	}

	// The endpoint reads the STORED document, so the scan-stamped
	// parsed.absolute_path is the grounding precondition for every bytes leg —
	// transcribed here from the served documents, not assumed.
	photoID := mediaItemIDByRel(t, client, baseURL, token, photoLib, photoRel)
	tvID := mediaItemIDByRel(t, client, baseURL, token, tvLib, tvRel)
	mediaAssertAbsolutePath(t, client, baseURL, token, photoID, photoPath)
	mediaAssertAbsolutePath(t, client, baseURL, token, tvID, tvPath)

	photoURL := baseURL + "/api/v1/items/" + photoID + "/media"
	tvURL := baseURL + "/api/v1/items/" + tvID + "/media"

	// --- bearer gate: no token → 401, never bytes ---
	if status, _, body := mediaDo(t, client, http.MethodGet, photoURL, ""); status != http.StatusUnauthorized {
		t.Fatalf("unauthenticated media GET: status %d, want 401 (body=%s)", status, body)
	}

	// --- photo original: 200, EXACT bytes, image headers ---
	photoWant := mediaReadFixture(t, photoPath)
	status, hdr, body := mediaDo(t, client, http.MethodGet, photoURL, token)
	if status != http.StatusOK {
		t.Fatalf("photo media GET: status %d, want 200 (body=%s)", status, body)
	}
	if string(body) != string(photoWant) {
		t.Fatalf("photo media bytes = %d bytes, want the EXACT fixture bytes (%d bytes)", len(body), len(photoWant))
	}
	if got := hdr.Get("Content-Type"); got != "image/jpeg" {
		t.Errorf("photo Content-Type = %q, want image/jpeg (derived from the extension)", got)
	}
	etag := hdr.Get("ETag")
	if etag == "" || strings.HasPrefix(etag, "W/") || !strings.HasPrefix(etag, "\"") {
		t.Errorf("photo ETag = %q, want a present STRONG entity tag (quoted, no W/ prefix)", etag)
	}
	if got := hdr.Get("Cache-Control"); got != "private, immutable" {
		t.Errorf("photo Cache-Control = %q, want %q", got, "private, immutable")
	}
	if got := hdr.Get("Content-Disposition"); !strings.Contains(got, "inline") {
		t.Errorf("photo Content-Disposition = %q, want inline (image content)", got)
	}

	// --- conditional re-request with the returned ETag → 304 ---
	condReq, err := http.NewRequest(http.MethodGet, photoURL, nil)
	if err != nil {
		t.Fatalf("new conditional request: %v", err)
	}
	condReq.Header.Set("Authorization", "Bearer "+token)
	condReq.Header.Set("If-None-Match", etag)
	condResp, err := client.Do(condReq)
	if err != nil {
		t.Fatalf("conditional media GET: %v", err)
	}
	condBody, err := io.ReadAll(condResp.Body)
	condResp.Body.Close()
	if err != nil {
		t.Fatalf("read conditional body: %v", err)
	}
	if condResp.StatusCode != http.StatusNotModified {
		t.Errorf("If-None-Match re-request: status %d, want 304 (body=%s)", condResp.StatusCode, condBody)
	}
	if len(condBody) != 0 {
		t.Errorf("If-None-Match re-request carried %d body bytes, want none", len(condBody))
	}

	// --- video original: 200, EXACT bytes, downloads-not-streams posture ---
	tvWant := mediaReadFixture(t, tvPath)
	status, hdr, body = mediaDo(t, client, http.MethodGet, tvURL, token)
	if status != http.StatusOK {
		t.Fatalf("tv media GET: status %d, want 200 (body=%s)", status, body)
	}
	if string(body) != string(tvWant) {
		t.Fatalf("tv media bytes = %d bytes, want the EXACT fixture bytes (%d bytes)", len(body), len(tvWant))
	}
	if ct := hdr.Get("Content-Type"); ct == "" {
		t.Errorf("tv Content-Type empty, want one derived from the .mkv extension")
	}
	if got := hdr.Get("Content-Disposition"); !strings.Contains(got, "attachment") {
		t.Errorf("tv Content-Disposition = %q, want attachment (non-image downloads, never streams)", got)
	}
	if hdr.Get("ETag") == "" || hdr.Get("Cache-Control") != "private, immutable" {
		t.Errorf("tv headers: ETag=%q Cache-Control=%q, want a strong ETag + private, immutable", hdr.Get("ETag"), hdr.Get("Cache-Control"))
	}

	// --- error contract over the wire ---
	var errBody struct {
		Error struct {
			Code    string `json:"code"`
			Message string `json:"message"`
		} `json:"error"`
	}
	if status := doRequest(t, client, http.MethodGet, baseURL+"/api/v1/items/media-unknown-id/media", token, nil, &errBody); status != http.StatusNotFound {
		t.Errorf("unknown id media GET: status %d, want 404", status)
	} else if errBody.Error.Code != "not_found" {
		t.Errorf("unknown id media GET: error.code = %q, want not_found (canonical error body)", errBody.Error.Code)
	}

	// The tv chain binds tv-parser (+ deferred external enrichers) but NO
	// frame-grabber, so the thumb variant deterministically lacks its path
	// fact → strict 404 (media-preview D6: no server-side fallback).
	if status := doRequest(t, client, http.MethodGet, tvURL+"?variant=thumb", token, nil, &errBody); status != http.StatusNotFound {
		t.Errorf("thumb without the fact: status %d, want 404", status)
	} else if errBody.Error.Code != "not_found" {
		t.Errorf("thumb without the fact: error.code = %q, want not_found", errBody.Error.Code)
	}

	// Unknown variant value → 400 bad_request.
	if status := doRequest(t, client, http.MethodGet, photoURL+"?variant=poster", token, nil, &errBody); status != http.StatusBadRequest {
		t.Errorf("unknown variant: status %d, want 400", status)
	} else if errBody.Error.Code != "bad_request" {
		t.Errorf("unknown variant: error.code = %q, want bad_request", errBody.Error.Code)
	}
}

// mediaCreateLibrary POSTs a library of the given module id and returns its id
// (the shipped createLibrary hardcodes module_id tv; media needs image + tv).
func mediaCreateLibrary(t *testing.T, c *http.Client, baseURL, token, root, moduleID, name string) int64 {
	t.Helper()
	body := createLibraryRequest{ModuleID: moduleID, RootPath: root, DisplayName: name}
	var resp libraryResponse
	if status := doRequest(t, c, http.MethodPost, baseURL+"/api/v1/libraries", token, body, &resp); status != http.StatusCreated {
		t.Fatalf("create %s library: HTTP %d, want 201", moduleID, status)
	}
	return resp.ID
}

// mediaItemIDByRel returns the id of the one item at rel (fatal when missing).
func mediaItemIDByRel(t *testing.T, c *http.Client, baseURL, token string, libID int64, rel string) string {
	t.Helper()
	it, ok := indexByPath(t, listItems(t, c, baseURL, token, libID))[rel]
	if !ok {
		t.Fatalf("item %q not persisted in lib %d", rel, libID)
	}
	return it.ID
}

// mediaAssertAbsolutePath transcribes the precondition the bytes legs stand on:
// the served document's parsed.absolute_path points at the real fixture file.
func mediaAssertAbsolutePath(t *testing.T, c *http.Client, baseURL, token, id, want string) {
	t.Helper()
	var resp struct {
		Item itemDTO `json:"item"`
	}
	if status := doRequest(t, c, http.MethodGet, baseURL+"/api/v1/items/"+id, token, nil, &resp); status != http.StatusOK {
		t.Fatalf("GET item %s: HTTP %d, want 200", id, status)
	}
	doc := parseAsyncDoc(t, resp.Item.Document)
	if got := asyncStr(doc.Parsed, "absolute_path"); got != want {
		t.Fatalf("item %s parsed.absolute_path = %q, want the fixture path %q (scan-stamped precondition)", id, got, want)
	}
}

// mediaReadFixture reads a fixture file's exact bytes (the 200-assertion's
// ground truth).
func mediaReadFixture(t *testing.T, path string) []byte {
	t.Helper()
	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("read fixture %s: %v", filepath.Base(path), err)
	}
	return data
}
